package fable.hideseek.imba.game;
import fable.hideseek.imba.config.BreakRulesConfig;import fable.hideseek.imba.item.SeekerSwordUtil;import fable.hideseek.imba.mask.MaskService;import fable.hideseek.imba.mask.MaskState;import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;import net.fabricmc.fabric.api.event.player.AttackBlockCallback;import net.fabricmc.fabric.api.event.player.UseBlockCallback;import net.fabricmc.fabric.api.event.player.UseEntityCallback;import net.minecraft.entity.decoration.ItemFrameEntity;import net.minecraft.inventory.Inventory;import net.minecraft.registry.RegistryKey;import net.minecraft.server.MinecraftServer;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.text.Text;import net.minecraft.util.ActionResult;import net.minecraft.world.World;import java.util.HashMap;import java.util.HashSet;import java.util.Map;import java.util.Set;import java.util.UUID;
public final class GameplayRulesHandler{private static boolean wasGameActive,wasReturnPhase;private static final Map<UUID,RegistryKey<World>>LAST_WORLD=new HashMap<>();private static final Map<UUID,Integer>LAST_SEEKER_SWORDS=new HashMap<>();private GameplayRulesHandler(){}public static void register(){UseEntityCallback.EVENT.register((player,world,hand,entity,hit)->{if(world.isClient||player.isCreative())return ActionResult.PASS;if(entity instanceof Inventory&&!BreakRulesConfig.isInteractiveEntityAllowed(entity.getType())){ConfigurableMessages.actionBar((ServerPlayerEntity)player,"restriction.interactive_entity",Text.literal("§cЭта интерактивная сущность запрещена настройками карты"));return ActionResult.FAIL;}if(entity instanceof ItemFrameEntity frame&&frame.getHeldItemStack().isEmpty()&&!player.getStackInHand(hand).isEmpty()){ConfigurableMessages.actionBar((ServerPlayerEntity)player,"restriction.item_frame",Text.literal("§cКласть предметы в рамки можно только в креативе"));return ActionResult.FAIL;}return ActionResult.PASS;});UseBlockCallback.EVENT.register((player,world,hand,hit)->{if(world.isClient||player.isCreative())return ActionResult.PASS;var pos=hit.getBlockPos();var state=world.getBlockState(pos);if(state.createScreenHandlerFactory(world,pos)!=null&&!BreakRulesConfig.isInteractiveAllowed(state.getBlock())){ConfigurableMessages.actionBar((ServerPlayerEntity)player,"restriction.interactive_block",Text.literal("§cЭтот интерактивный блок запрещён настройками карты"));return ActionResult.FAIL;}return ActionResult.PASS;});AttackBlockCallback.EVENT.register((player,world,hand,pos,direction)->{if(world.isClient||player.isCreative()||world.getBlockState(pos).isAir())return ActionResult.PASS;if(BreakRulesConfig.isAdventureBreakAllowed(world.getBlockState(pos).getBlock())){world.breakBlock(pos,false,player);return ActionResult.SUCCESS;}return ActionResult.PASS;});ServerTickEvents.END_SERVER_TICK.register(GameplayRulesHandler::tick);}private static void tick(MinecraftServer server){boolean active=GameManager.isGameActive(),ret=GameManager.isReturnPhase();if(!wasReturnPhase&&ret)for(ServerPlayerEntity p:server.getPlayerManager().getPlayerList())if(GameRoles.isHider(p))p.getInventory().clear();wasReturnPhase=ret;Set<UUID>online=new HashSet<>();for(ServerPlayerEntity p:server.getPlayerManager().getPlayerList()){UUID id=p.getUuid();online.add(id);RegistryKey<World>w=p.getWorld().getRegistryKey();int swords=countSeekerSwords(p);RegistryKey<World>pw=LAST_WORLD.get(id);Integer pc=LAST_SEEKER_SWORDS.get(id);if(GameRoles.isSeeker(p)&&!GameManager.isPrepareLocked(p)&&pw!=null&&pc!=null&&!pw.equals(w)&&swords>pc){removeExtraSeekerSwords(p,swords-pc);swords=countSeekerSwords(p);}LAST_WORLD.put(id,w);LAST_SEEKER_SWORDS.put(id,swords);}LAST_WORLD.keySet().removeIf(id->!online.contains(id));LAST_SEEKER_SWORDS.keySet().removeIf(id->!online.contains(id));if(wasGameActive&&!active)cleanupAfterRound(server);wasGameActive=active;}private static int countSeekerSwords(ServerPlayerEntity p){int c=0;for(int i=0;i<p.getInventory().size();i++)if(SeekerSwordUtil.isSeekerSword(p.getInventory().getStack(i)))c++;return c;}private static void removeExtraSeekerSwords(ServerPlayerEntity p,int amount){for(int i=p.getInventory().size()-1;i>=0&&amount>0;i--)if(SeekerSwordUtil.isSeekerSword(p.getInventory().getStack(i))){p.getInventory().setStack(i,net.minecraft.item.ItemStack.EMPTY);amount--;}}private static void cleanupAfterRound(MinecraftServer server){GameRoles.clearParticipantTeams(server);for(ServerPlayerEntity p:server.getPlayerManager().getPlayerList()){if(MaskState.hasMask(p.getUuid()))MaskService.resetMask(p);p.setSneaking(false);p.setNoGravity(false);p.calculateDimensions();p.setVelocity(0,0,0);p.fallDistance=0;p.requestTeleport(p.getX(),p.getY(),p.getZ());}}}
